(
  /* Extract timezone */
  $timezone := $coalesce([$.setting.edges[0].node.defaultValue, $momentTzGuess()]);
  
  /* Calculate hour boundaries (previous hour) in local time */
  $nowLocal := $moment().tz($timezone);
  $hourStartLocal := $nowLocal.startOf('hour').subtract(1, 'hour');
  $hourEndLocal := $moment($hourStartLocal).add(1, 'hour');
  
  /* Format as ISO string to get UTC representation */
  $hourStartQuery := $hourStartLocal.toISOString();
  $hourEndQuery := $hourEndLocal.toISOString();
  $periodAt := $hourStartLocal.toISOString();
  $dayHour := $number($hourStartLocal.format('H'));
  
  /* Build workcenter → scheduleGroupId mapping */
  $workcenters := $.workcenter.edges.node;
  $workcenterScheduleGroup := $merge($workcenters.{
    id: scheduleGroupId
  });
  
  /* Get unique scheduleGroupIds */
  $scheduleGroupIds := $distinct($workcenters.scheduleGroupId)[$ != null];
  
  /* Build scheduleGroupId → schedule info mapping (with shift start) */
  $schedulesByGroup := $merge($scheduleGroupIds.(
    $groupId := $;
    $currentSchedules := $scheduleGroup($groupId).getCurrentSchedules(
      $hourStartLocal, 
      $hourEndLocal, 
      { "inclusive": true }
    );
    $activeSchedule := $currentSchedules[0];
    { 
      ($groupId): $activeSchedule ? {
        "scheduleId": $activeSchedule.scheduleId,
        "scheduleName": $activeSchedule.name,
        "isActive": true,
        "shiftStartAt": $activeSchedule.startAt,
        "shiftEndAt": $activeSchedule.endAt
      } : {
        "scheduleId": null,
        "scheduleName": "Unscheduled",
        "isActive": false,
        "shiftStartAt": null,
        "shiftEndAt": null
      }
    }
  ));
  
  /* Return combined config */
  {
    "boundaries": {
      "timezone": $timezone,
      "hourStartQuery": $hourStartQuery,
      "hourEndQuery": $hourEndQuery,
      "periodAt": $periodAt,
      "dayHour": $dayHour
    },
    "workcenterScheduleGroup": $workcenterScheduleGroup,
    "schedulesByGroup": $schedulesByGroup
  }
