'use strict';

var oeeConfig = $state.context.oeeConfig;
var boundaries = oeeConfig.boundaries;

var hourStartQuery = boundaries.hourStartQuery;
var hourEndQuery = boundaries.hourEndQuery;
var hourStartMs = new Date(hourStartQuery).getTime();
var hourEndMs = new Date(hourEndQuery).getTime();
var dayHour = boundaries.dayHour;

var productionEdges = $.productionLog?.edges || [];
var historyEdges = $.workcenterHistory?.edges || [];
var existingOeeEdges = $.oeeHourly?.edges || [];

// ========================================
// ISO 22400 COMPLIANT HELPER FUNCTIONS
// ========================================

function calcOverlapMs(startMs1, endMs1, startMs2, endMs2) {
  var start = Math.max(startMs1, startMs2);
  var end = Math.min(endMs1, endMs2);
  return Math.max(0, end - start);
}

function calcShiftHour(shiftStartAt, periodStartAt) {
  if (!shiftStartAt || !periodStartAt) return 0;
  
  var shiftStartMs = new Date(shiftStartAt).getTime();
  var periodMs = new Date(periodStartAt).getTime();
  
  var hoursIntoShift = (periodMs - shiftStartMs) / (60 * 60 * 1000);
  return Math.max(1, Math.floor(hoursIntoShift) + 1);
}

// ========================================
// STEP 1: Group existing OEE periods by workcenter
// Include ALL periods with scheduleId
// ========================================
var oeePeriodsMap = {};

for (var i = 0; i < existingOeeEdges.length; i++) {
  var oeeNode = existingOeeEdges[i].node;
  var wcId = oeeNode.workcenterId;
  
  // ONLY process periods that have a scheduleId
  if (!oeeNode.scheduleId) {
    continue;
  }
  
  if (!oeePeriodsMap[wcId]) {
    oeePeriodsMap[wcId] = [];
  }
  
oeePeriodsMap[wcId].push({
  id: oeeNode.id,
  periodStartMs: new Date(oeeNode.periodStartAt).getTime(),
  periodEndMs: new Date(oeeNode.periodEndAt).getTime(),
  periodStartAt: oeeNode.periodStartAt,
  periodEndAt: oeeNode.periodEndAt,
  scheduleId: oeeNode.scheduleId,
  scheduleName: oeeNode.schedule ? oeeNode.schedule.name : 'Unscheduled',
  shift: oeeNode.shift || null,
  shiftHour: oeeNode.shiftHour || 0,  // <-- ADD THIS LINE
  isException: (oeeNode.shift === 'exception'),
  exists: true
});
}

for (var wcKey in oeePeriodsMap) {
  oeePeriodsMap[wcKey].sort(function(a, b) {
    return a.periodStartMs - b.periodStartMs;
  });
}

// ========================================
// STEP 2: Group production logs by workcenter
// ========================================
var productionByWorkcenter = {};

for (var p = 0; p < productionEdges.length; p++) {
  var pNode = productionEdges[p].node;
  var wcId = pNode.workcenterId;
  
  if (!productionByWorkcenter[wcId]) {
    productionByWorkcenter[wcId] = [];
  }
  
  var occurAtMs = new Date(pNode.occurAt).getTime();
  var cycleTime = pNode.product?.standardCycleTime || 30;
  var goodQty = pNode.quantityGood || 0;
  var scrapQty = pNode.quantityScrap || 0;
  
  productionByWorkcenter[wcId].push({
    occurAtMs: occurAtMs,
    occurAt: pNode.occurAt,
    quantityGood: goodQty,
    quantityScrap: scrapQty,
    cycleTime: cycleTime,
    productId: pNode.productId,
    scheduleId: pNode.scheduleId
  });
}

// ========================================
// STEP 3: Group history by workcenter
// ========================================
var historyByWorkcenter = {};

for (var h = 0; h < historyEdges.length; h++) {
  var hNode = historyEdges[h].node;
  var hWcId = hNode.workcenterId;
  
  if (!historyByWorkcenter[hWcId]) {
    historyByWorkcenter[hWcId] = [];
  }
  
  var occurAtMs = new Date(hNode.occurAt).getTime();
  var endAtMs = hNode.endAt ? new Date(hNode.endAt).getTime() : hourEndMs;
  
  historyByWorkcenter[hWcId].push({
    occurAtMs: occurAtMs,
    endAtMs: endAtMs,
    occurAt: hNode.occurAt,
    endAt: hNode.endAt,
    mode: hNode.mode,
    state: hNode.state,
    modeId: hNode.modeId,
    scheduleId: hNode.scheduleId,
    scheduleName: hNode.schedule ? hNode.schedule.name : null
  });
}

// ========================================
// STEP 4: Helper to check if period has data
// ========================================
function periodHasData(wcId, periodStartMs, periodEndMs, prodLogs, histRecords) {
