  var periods = oeePeriodsMap[wcId] || [];
  var prodLogs = productionByWorkcenter[wcId] || [];
  var histRecords = historyByWorkcenter[wcId] || [];
  
  if (periods.length === 0) {
    console.log('No OEE periods defined for workcenter:', wcId);
    continue;
  }
  
  for (var pi = 0; pi < periods.length; pi++) {
    var period = periods[pi];
    var periodStartMs = period.periodStartMs;
    var periodEndMs = period.periodEndMs;
    var periodDurationMs = periodEndMs - periodStartMs;
    
    // ========================================
    // EXCECustomer-DON HANDLING:
    // Skip exceptions that have no data
    // ========================================
    if (period.isException) {
