      }
    }
    
    // ========================================
    // ALLOCATE PRODUCTION DATA TO THIS PERIOD
    // ========================================
    var periodProduction = {
      goodCount: 0,
      scrapCount: 0,
      totalCount: 0,
      weightedCycleTimeSum: 0
    };
    
    for (var pl = 0; pl < prodLogs.length; pl++) {
      var log = prodLogs[pl];
      
      if (log.occurAtMs >= periodStartMs && log.occurAtMs < periodEndMs) {
        periodProduction.goodCount += log.quantityGood;
        periodProduction.scrapCount += log.quantityScrap;
        var totalQty = log.quantityGood + log.quantityScrap;
        periodProduction.totalCount += totalQty;
        periodProduction.weightedCycleTimeSum += totalQty * log.cycleTime;
      }
    }
    
    // ========================================
    // ALLOCATE HISTORY DATA TO THIS PERIOD
    // ========================================
    var periodTime = {
      runTimeMs: 0,
      plannedDowntimeMs: 0,
      unplannedDowntimeMs: 0,
      setupMs: 0,
      topDowntimeMs: 0,
      accountedMs: 0
    };
    
    for (var hr = 0; hr < histRecords.length; hr++) {
      var hist = histRecords[hr];
      
      var overlapMs = calcOverlapMs(
        hist.occurAtMs,
        hist.endAtMs,
        periodStartMs,
        periodEndMs
      );
      
      if (overlapMs <= 0) continue;
      
      periodTime.accountedMs += overlapMs;
      
      var mode = hist.mode;
      var state = hist.state;
      
      if (state && state.isProducing === true) {
        periodTime.runTimeMs += overlapMs;
      }
      else if (mode && mode.countAsPlannedDowntime === true) {
        periodTime.plannedDowntimeMs += overlapMs;
      }
      else {
        periodTime.unplannedDowntimeMs += overlapMs;
        if (overlapMs > periodTime.topDowntimeMs) {
          periodTime.topDowntimeMs = overlapMs;
        }
      }
      
      if (hist.modeId === 'setup' || (mode && mode.oeeImpact === 'setup')) {
        periodTime.setupMs += overlapMs;
      }
    }
    
    // ========================================
    // HANDLE UNACCOUNTED TIME
    // If no history data at all, set to unplanned downtime
    // ========================================
    var unaccountedMs = periodDurationMs - periodTime.accountedMs;
    if (unaccountedMs > 0) {
      periodTime.unplannedDowntimeMs += unaccountedMs;
      periodTime.accountedMs = periodDurationMs;
    }
    
    // ========================================
    // CALCULATE OEE METRICS (ISO 22400)
    // ========================================
    var plannedProductionTimeMs = periodDurationMs - periodTime.plannedDowntimeMs;
    
    var idealCycleTime = periodProduction.totalCount > 0
      ? periodProduction.weightedCycleTimeSum / periodProduction.totalCount
      : 30;
    
    var actualCycleTime = periodProduction.totalCount > 0
      ? (periodTime.runTimeMs / 1000) / periodProduction.totalCount
      : 0;
    
    var idealCount = (periodTime.runTimeMs > 0 && idealCycleTime > 0)
      ? (periodTime.runTimeMs / 1000) / idealCycleTime
      : 0;
    
    // Availability = Operating Time / Planned Production Time
    var availability = plannedProductionTimeMs > 0
      ? Math.min(periodTime.runTimeMs / plannedProductionTimeMs, 1)
      : 0;
    
    // Performance = Actual Output / Ideal Output
    var performance = idealCount > 0
      ? Math.min(periodProduction.totalCount / idealCount, 1)
      : 0;
    
    // Quality = Good Units / Total Units
    var quality = periodProduction.totalCount > 0
      ? periodProduction.goodCount / periodProduction.totalCount
      : 1;
    
    // OEE = A × P × Q
    var oee = availability * performance * quality;
    
    // Shift hour calculation (placeholder - needs schedule.shiftStartAt)
  var shiftHour = period.shiftHour || 0;
    
    // ========================================
    // BUILD PAYLOAD WITH BOTH CREATE AND UPDATE
    // ========================================
    var recordId = period.id || (wcId + '-' + period.periodStartAt);
    
    payload.push({
      "where": {
        "id": recordId
      },
      "create": {
        "id": recordId,
        "workcenterId": wcId,
        "periodStartAt": period.periodStartAt,
        "periodEndAt": period.periodEndAt,
        "dayHour": dayHour,
        "shiftHour": shiftHour,
        "shift": period.shift || period.scheduleName,
        "scheduleId": period.scheduleId,
        "plannedMinutes": plannedProductionTimeMs,
        "runMinutes": periodTime.runTimeMs,
        "downtimeMinutes": periodTime.unplannedDowntimeMs,
        "plannedDowntimeMinutes": periodTime.plannedDowntimeMs,
        "setupMinutes": periodTime.setupMs,
        "topDowntime": periodTime.topDowntimeMs,
        "idealCycleTime": Math.round(idealCycleTime * 1000),
        "actualCycleTime": Math.round(actualCycleTime * 1000),
        "goodUnits": periodProduction.goodCount,
        "scrapUnits": periodProduction.scrapCount,
        "totalUnits": periodProduction.totalCount,
        "idealUnits": Math.round(idealCount * 100) / 100,
        "availability": Math.round(availability * 10000) / 10000,
        "performance": Math.round(performance * 10000) / 10000,
        "quality": Math.round(quality * 10000) / 10000,
        "oee": Math.round(oee * 10000) / 10000
      },
      "update": {
        "shift": period.shift || period.scheduleName,
        "scheduleId": period.scheduleId,
        "dayHour": dayHour,
        "shiftHour": shiftHour,
        "plannedMinutes": plannedProductionTimeMs,
        "runMinutes": periodTime.runTimeMs,
        "downtimeMinutes": periodTime.unplannedDowntimeMs,
        "plannedDowntimeMinutes": periodTime.plannedDowntimeMs,
        "setupMinutes": periodTime.setupMs,
        "topDowntime": periodTime.topDowntimeMs,
        "idealCycleTime": Math.round(idealCycleTime * 1000),
        "actualCycleTime": Math.round(actualCycleTime * 1000),
        "goodUnits": periodProduction.goodCount,
        "scrapUnits": periodProduction.scrapCount,
        "totalUnits": periodProduction.totalCount,
        "idealUnits": Math.round(idealCount * 100) / 100,
        "availability": Math.round(availability * 10000) / 10000,
        "performance": Math.round(performance * 10000) / 10000,
        "quality": Math.round(quality * 10000) / 10000,
        "oee": Math.round(oee * 10000) / 10000
      }
    });
  }
}

console.log('OEE payload:', payload.length, 'periods processed');

return { "payload": payload };

data.mutation:
mutation UpsertOeeHourly($payload: [OeeHourlyUpsertPayloadInput!]!) {
  upsertOeeHourly(payload: $payload) {
    id
    workcenterId
    oee
    availability
    performance
    quality
  }
}

data.query:
query OeeDataForHour(
  $productionWhere: ProductionLogWhereInput
  $historyWhere: WorkcenterHistoryWhereInput
  $oeeHourlyWhere: OeeHourlyWhereInput
) {
  productionLog(where: $productionWhere, first: 100000) {
    edges {
      node {
        id
        workcenterId
        occurAt
        productId
        scheduleId
        product {
          standardCycleTime
          targetYield
        }
        quantityGood
        quantityScrap
        cycleTime
      }
    }
  }
  
  workcenterHistory(where: $historyWhere, first: 100000) {
    edges {
      node {
        id
        workcenterId
        modeId
        stateId
        scheduleId
        occurAt
        endAt
        mode {
          countAsDowntime
          countAsProductionTime
          countAsPlannedDowntime
          oeeImpact
        }
        state {
          isProducing
          isPerformanceLoss
          isFault
        }
        schedule {
          id
          name
        }
      }
    }
  }
  
  oeeHourly(where: $oeeHourlyWhere, first: 100000) {
    edges {
      node {
        id
        workcenterId
        periodStartAt
        periodEndAt
        shift
        shiftHour
        scheduleId
        schedule {
          id
          name
        }
      }
    }
  }
}

